'use client';

import type { ButtonHTMLAttributes, ReactNode, Ref } from 'react';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';
import { Spinner } from '@/components/base/spinner/spinner';

export type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger' | 'soft' | 'outline' | 'solid' | 'quiet';
export type ButtonSize = 'medium' | 'small' | 'xs';

type NativeButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children'>;
type ContentProps =
  | { iconOnly: true; 'aria-label': string; leadingIcon: IconComponent; children?: never }
  | { iconOnly?: false; children: ReactNode; leadingIcon?: IconComponent };

export type ButtonProps = NativeButtonProps & ContentProps & {
  variant?: ButtonVariant;
  size?: ButtonSize;
  trailingIcon?: IconComponent;
  isLoading?: boolean;
  loadingLabel?: string;
  ref?: Ref<HTMLButtonElement>;
};

const base = 'ui-button inline-flex shrink-0 items-center justify-center whitespace-nowrap select-none outline-none';
const sizes: Record<ButtonSize, string> = {
  medium: 'h-9 rounded-[10px] px-2 gap-0.5',
  small: 'h-8 rounded-lg px-2 gap-0.5',
  xs: 'h-6 rounded-[5px] px-2 gap-0.5',
};
export const buttonIconClassNames: Record<ButtonSize, string> = { medium: 'size-5', small: 'size-[18px]', xs: 'size-3.5' };
export function buttonClassNames(size: ButtonSize, iconOnly = false, className?: string) {
  return cx(base, sizes[size], iconOnly && 'ui-button--icon-only !p-0', className);
}

export function Button({
  variant = 'primary',
  size = 'medium',
  iconOnly = false,
  leadingIcon: LeadingIcon,
  trailingIcon: TrailingIcon,
  children,
  className,
  type = 'button',
  isLoading = false,
  loadingLabel,
  disabled,
  onClick,
  onKeyDown,
  ...props
}: ButtonProps) {
  return (
    <button
      {...props}
      type={isLoading && type === 'submit' ? 'button' : type}
      disabled={disabled}
      aria-disabled={isLoading || props['aria-disabled'] || undefined}
      aria-busy={isLoading || undefined}
      aria-description={isLoading && loadingLabel ? loadingLabel : props['aria-description']}
      data-variant={variant}
      data-size={size}
      data-icon-only={iconOnly || undefined}
      data-loading={isLoading || undefined}
      data-loading-label={loadingLabel !== undefined || undefined}
      className={buttonClassNames(size, iconOnly, className)}
      onClick={event => { if (isLoading || props['aria-disabled'] === true || props['aria-disabled'] === 'true') { event.preventDefault(); event.stopPropagation(); return; } onClick?.(event); }}
      onKeyDown={event => { if (isLoading && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); event.stopPropagation(); return; } onKeyDown?.(event); }}
    >
      {LeadingIcon && <span className="ui-button__leading-slot" aria-hidden><LeadingIcon className={cx(buttonIconClassNames[size], 'ui-button__leading-icon')}/></span>}
      {!iconOnly && <span className="ui-button__label">{children}</span>}
      {!iconOnly && TrailingIcon && <TrailingIcon className={buttonIconClassNames[size]} aria-hidden />}
      <Spinner className="ui-button__busy-spinner" size={size === 'xs' ? 'xs' : size === 'small' ? 'sm' : 'md'}/>
    </button>
  );
}

import type { ButtonHTMLAttributes, Ref } from 'react';
import { cx } from '@/utils/cx';

export type CloseButtonSize = '2xs' | 'xs' | 'sm' | 'md';

export type CloseButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'aria-label'> & {
  size?: CloseButtonSize;
  ref?: Ref<HTMLButtonElement>;
  'aria-label': string;
};

const glyphSizes: Record<CloseButtonSize, number> = { '2xs': 8, xs: 11, sm: 13, md: 17 };
const strokes: Record<CloseButtonSize, number> = { '2xs': 1.6, xs: 2, sm: 2, md: 2.5 };

export function CloseButton({ size = 'xs', className, type = 'button', ...props }: CloseButtonProps) {
  const glyph = glyphSizes[size];
  const inset = size === '2xs' ? 1.4 : 2;
  return (
    <button type={type} data-size={size} className={cx('ui-close-button', className)} {...props}>
      <svg width={glyph} height={glyph} viewBox={`0 0 ${glyph} ${glyph}`} fill="none" aria-hidden="true">
        <path d={`M${inset} ${inset}L${glyph - inset} ${glyph - inset}M${glyph - inset} ${inset}L${inset} ${glyph - inset}`} stroke="currentColor" strokeWidth={strokes[size]} strokeLinecap="round" />
      </svg>
    </button>
  );
}

'use client';

import {useMemo,useRef,type AnchorHTMLAttributes,type ButtonHTMLAttributes,type Ref} from 'react';
import {mergeRefs} from 'react-aria';
import {useMotionTokens} from '@/hooks/use-motion-tokens';
import { Button as AriaButton, ProgressBar as AriaProgressBar, type ButtonProps as AriaButtonProps } from 'react-aria-components';
import { AnimatePresence, motion } from 'motion/react';
import { useMediaQuery } from '@/hooks/use-media-query';
import { Spinner } from '@/components/base/spinner/spinner';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';

export type IconButtonSize = 'medium' | 'small' | 'xs';

export type IconButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'aria-label' | 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick'> & Pick<AriaButtonProps, 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick' | 'isPending' | 'preventFocusOnPress'> & {
  icon: IconComponent;
  /** Animate a glyph change without moving or remounting its button. */
  iconKey?: string | number;
  pendingLabel?: string;
  size?: IconButtonSize;
  variant?: 'secondary' | 'ghost';
  badge?: number;
  ref?: Ref<HTMLButtonElement>;
  'aria-label': string;
};

export type IconLinkButtonProps = Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'children' | 'aria-label'> & {
  icon: IconComponent;
  size?: IconButtonSize;
  'aria-label': string;
};

export function IconButton({ icon: Icon, iconKey, pendingLabel = 'Working', isPending, size = 'medium', variant = 'secondary', badge, className, type = 'button', disabled, value, ref, ...props }: IconButtonProps) {
  const reducedMotion = useMediaQuery('(prefers-reduced-motion: reduce)');
  const root=useRef<HTMLButtonElement>(null),composed=useMemo(()=>mergeRefs(root,ref),[ref]),tokens=useMotionTokens(root);
  return <AriaButton {...props} ref={composed} type={type} value={value === undefined ? undefined : String(value)} isDisabled={disabled} isPending={isPending} data-size={size} data-variant={variant} className={cx('ui-icon-button', className)}>{iconKey === undefined ? <Icon className="ui-icon-button__icon" aria-hidden /> : <span className="ui-icon-button__glyph" aria-hidden><AnimatePresence initial={false}><motion.span key={iconKey} data-icon-key={iconKey} initial={reducedMotion ? false : { opacity: 0, scale: .65, y: 2 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={reducedMotion ? { opacity: 0 } : { opacity: 0, scale: .65, y: -2 }} transition={{ duration: reducedMotion ? 0 : tokens.fast, ease: tokens.ease }}><Icon className="ui-icon-button__icon"/></motion.span></AnimatePresence></span>}<span className="ui-icon-button__pending" aria-hidden><Spinner size={size === 'medium' ? 'md' : 'sm'}/></span>{isPending && <AriaProgressBar aria-label={pendingLabel} isIndeterminate className="sr-only"/>}{badge !== undefined && badge > 0 && <span className="ui-icon-button__badge" aria-hidden>{badge > 99 ? '99+' : badge}</span>}</AriaButton>;
}

export function IconLinkButton({ icon: Icon, size = 'medium', className, ...props }: IconLinkButtonProps) {
  return <a data-size={size} className={cx('ui-icon-button', className)} {...props}><Icon className="ui-icon-button__icon" aria-hidden /></a>;
}

import type { HTMLAttributes, ReactNode, Ref } from 'react';
import { cx } from '@/utils/cx';

export type CardProps = HTMLAttributes<HTMLDivElement> & { ref?: Ref<HTMLDivElement>; variant?: 'bordered' | 'raised' | 'soft'; padding?: 'none' | 'small' | 'medium' | 'large' };
export function Card({ variant = 'bordered', padding = 'medium', className, ...props }: CardProps) {
  return <div {...props} className={cx('ui-card', className)} data-variant={variant} data-padding={padding}/>;
}
export function CardHeader({ title, description, actions, leading }: { title: string; description?: string; actions?: ReactNode; leading?: ReactNode }) {
  return <header className="ui-card__header">{leading && <span className="ui-card__leading" aria-hidden>{leading}</span>}<div><h3>{title}</h3>{description && <p>{description}</p>}</div>{actions && <div className="ui-card__actions">{actions}</div>}</header>;
}
export function CardFooter({ className, ...props }: HTMLAttributes<HTMLDivElement>) { return <div {...props} className={cx('ui-card__footer', className)}/>; }

export type CheckboxSize = 'sm' | 'md';

export type CheckboxGlyphState = {
  isSelected: boolean;
  isIndeterminate: boolean;
  isFocusVisible: boolean;
  isDisabled: boolean;
  isHovered: boolean;
};

export function CheckboxGlyph({ state, size = 'md' }: { state: CheckboxGlyphState; size?: CheckboxSize }) {
  const marked = state.isSelected || state.isIndeterminate;
  return <span className="ui-checkbox__box" data-size={size} data-marked={marked || undefined} data-hovered={state.isHovered || undefined} data-focus-visible={state.isFocusVisible || undefined} data-disabled={state.isDisabled || undefined} aria-hidden="true">
    <svg viewBox="0 0 16 16" fill="none">
      {state.isIndeterminate ? <path d="M4.2 8h7.6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" /> : state.isSelected ? <path d="m3.8 8 2.7 2.6 5.7-5.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" pathLength="1" className="ui-checkbox__tick" /> : null}
    </svg>
  </span>;
}

'use client';

import type { ReactNode } from 'react';
import { Checkbox as AriaCheckbox } from 'react-aria-components';
import type { CheckboxProps as AriaCheckboxProps } from 'react-aria-components';
import { cx } from '@/utils/cx';
import { useFieldDisabled } from '@/components/base/field/field-context';
import { CheckboxGlyph, type CheckboxSize } from './checkbox-glyph';

export type CheckboxProps = Omit<AriaCheckboxProps, 'children'> & {
  children?: ReactNode;
  size?: CheckboxSize;
};

export function Checkbox({ children, size = 'md', className, ...props }: CheckboxProps) {
  const isDisabled = useFieldDisabled(props.isDisabled);
  return <AriaCheckbox {...props} isDisabled={isDisabled} data-size={size} className={state => cx('ui-checkbox', typeof className === 'function' ? className(state) : className)}>
    {state => <><CheckboxGlyph state={state} size={size} />{children != null && <span className="ui-checkbox__label">{children}</span>}</>}
  </AriaCheckbox>;
}

import type { HTMLAttributes, ReactNode } from 'react';
import { cx } from '@/utils/cx';

export type CollapsibleProps = Omit<HTMLAttributes<HTMLDivElement>, 'children'> & { isOpen: boolean; children: ReactNode };

/** Keep descendants mounted while hiding their focus targets and animating flow. */
export function Collapsible({ isOpen, children, className, ...props }: CollapsibleProps) {
  return <div {...props} className={cx('ui-collapsible', className)} data-open={isOpen || undefined} aria-hidden={!isOpen} inert={!isOpen}>
    <div className="ui-collapsible__inner"><div className="ui-collapsible__content">{children}</div></div>
  </div>;
}

import type { ReactNode } from 'react';
import { cx } from '@/utils/cx';

export type EmptyStateProps = {
  title: string;
  description?: ReactNode;
  icon?: ReactNode;
  actions?: ReactNode;
  children?: ReactNode;
  size?: 'small' | 'medium' | 'large';
  variant?: 'plain' | 'bordered' | 'soft';
  className?: string;
};

export function EmptyState({ title, description, icon, actions, children, size = 'medium', variant = 'plain', className }: EmptyStateProps) {
  return <div className={cx('ui-empty-state', className)} data-size={size} data-variant={variant}>
    {icon && <div className="ui-empty-state__icon" aria-hidden>{icon}</div>}<h3>{title}</h3>{description && <p>{description}</p>}{actions && <div className="ui-empty-state__actions">{actions}</div>}{children && <div className="ui-empty-state__detail">{children}</div>}
  </div>;
}

'use client';

import {createContext, useContext} from 'react';

export const FieldSetDisabledContext = createContext(false);

/** An individual control cannot re-enable itself inside a disabled fieldset. */
export function useFieldDisabled(disabled?: boolean) {
  return useContext(FieldSetDisabledContext) || disabled;
}

'use client';

import { ProgressBar, Label, type ProgressBarProps } from 'react-aria-components';
import { cx } from '@/utils/cx';

export type ProgressProps = Omit<ProgressBarProps, 'children' | 'className'> & {
  label: string;
  hideLabel?: boolean;
  showValue?: boolean;
  variant?: 'bar' | 'ring';
  size?: 'small' | 'medium' | 'large';
  tone?: 'accent' | 'success' | 'warning' | 'danger';
  className?: string;
};

export function Progress({ label, hideLabel = false, showValue = true, variant = 'bar', size = 'medium', tone = 'accent', className, value, minValue = 0, maxValue = 100, isIndeterminate = false, ...props }: ProgressProps) {
  const minimum = Number.isFinite(minValue) ? minValue : 0;
  const maximum = Number.isFinite(maxValue) && maxValue > minimum ? maxValue : minimum + 100;
  const indefinite = isIndeterminate || value == null || !Number.isFinite(value);
  const boundedValue = indefinite ? undefined : Math.max(minimum, Math.min(maximum, value!));
  return <ProgressBar {...props} value={boundedValue} minValue={minimum} maxValue={maximum} isIndeterminate={indefinite} className={cx('ui-progress', className)} data-variant={variant} data-size={size} data-tone={tone}>
    {({ percentage, valueText }) => <>
      <div className="ui-progress__heading"><Label className={cx('ui-progress__label', hideLabel && 'sr-only')}>{label}</Label>{showValue && variant === 'bar' && !indefinite && <span className="ui-progress__value" aria-hidden>{valueText}</span>}</div>
      {variant === 'ring' ? <div className="ui-progress__ring" data-indeterminate={indefinite || undefined}>
        <svg viewBox="0 0 48 48" aria-hidden><circle cx="24" cy="24" r="20" className="ui-progress__track-circle"/><circle cx="24" cy="24" r="20" className="ui-progress__fill-circle" pathLength="100" strokeDasharray={indefinite ? '24 76' : '100'} strokeDashoffset={indefinite ? 0 : 100 - (percentage ?? 0)}/></svg>
        {showValue && !indefinite && <span aria-hidden>{valueText}</span>}
      </div> : <div className="ui-progress__track" data-indeterminate={indefinite || undefined}><span className="ui-progress__fill" style={{ width: indefinite ? '36%' : `${percentage ?? 0}%` }}/></div>}
    </>}
  </ProgressBar>;
}

import type { CSSProperties } from 'react';
import { cx } from '@/utils/cx';

export type SpinnerProps = {
  size?: 'xs' | 'sm' | 'md' | 'lg';
  label?: string;
  className?: string;
  style?: CSSProperties;
};

/** Omit the label when a containing busy control already names the operation. */
export function Spinner({ size = 'md', label, className, style }: SpinnerProps) {
  return <span className={cx('ui-spinner', className)} data-size={size} role={label ? 'status' : undefined} aria-label={label} aria-hidden={!label || undefined} style={style}>
    <svg viewBox="0 0 24 24" fill="none" aria-hidden><circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2" opacity=".18"/><path d="M12 3a9 9 0 0 1 9 9" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
  </span>;
}

'use client';

import { useEffect, useId, useRef, useState, type ReactNode } from 'react';
import { AnimatePresence, motion, useIsPresent, useReducedMotion } from 'motion/react';
import { RiArrowDownSLine } from '@remixicon/react';
import { Button, type ButtonProps } from '@/components/base/buttons/button';
import { Card, CardHeader, type CardProps } from '@/components/base/card/card';
import { Checkbox } from '@/components/base/checkbox/checkbox';
import { CloseButton } from '@/components/base/buttons/close-button';
import { Collapsible } from '@/components/base/collapsible/collapsible';
import { IconButton } from '@/components/base/buttons/icon-button';
import { Progress } from '@/components/base/progress/progress';
import { EmptyState } from '@/components/base/empty-state/empty-state';
import { cx } from '@/utils/cx';

export type OnboardingTask = {
  id: string;
  title: string;
  description?: string;
  isOptional?: boolean;
  isDisabled?: boolean;
  action?: { label: string; onPress: () => void; isLoading?: boolean; variant?: ButtonProps['variant'] };
};
export type OnboardingChecklistProps = {
  items: OnboardingTask[];
  title?: string;
  description?: string;
  completedKeys?: string[];
  defaultCompletedKeys?: string[];
  onCompletedChange?: (keys: string[]) => void;
  onComplete?: () => void;
  isReadOnly?: boolean;
  isExpanded?: boolean;
  defaultExpanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;
  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  dismissible?: boolean;
  onDismiss?: () => void;
  density?: 'normal' | 'compact';
  variant?: 'bordered' | 'soft' | 'raised';
  footer?: ReactNode;
  className?: string;
};

function ChecklistSurface(props: CardProps) {
  const present = useIsPresent();
  return <Card {...props} inert={!present} aria-hidden={!present || undefined}/>;
}

export function OnboardingChecklist({ items, title = 'Set up your workspace', description, completedKeys, defaultCompletedKeys = [], onCompletedChange, onComplete, isReadOnly = false, isExpanded, defaultExpanded = true, onExpandedChange, isOpen, defaultOpen = true, onOpenChange, dismissible = false, onDismiss, density = 'normal', variant = 'bordered', footer, className }: OnboardingChecklistProps) {
  const [internalKeys, setInternalKeys] = useState(defaultCompletedKeys);
  const [internalExpanded, setInternalExpanded] = useState(defaultExpanded);
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const completed = completedKeys ?? internalKeys, expanded = isExpanded ?? internalExpanded, open = isOpen ?? internalOpen;
  const required = items.filter(item => !item.isOptional), done = required.filter(item => completed.includes(item.id)).length;
  const complete = required.length > 0 && done === required.length;
  const wasComplete = useRef(complete), completeCallback = useRef(onComplete);
  completeCallback.current = onComplete;
  const id = useId(), reduced = useReducedMotion();
  useEffect(() => {
    if (complete && !wasComplete.current) completeCallback.current?.();
    wasComplete.current = complete;
  }, [complete]);
  function changeCompleted(key: string, selected: boolean) {
    const item = items.find(item => item.id === key);
    if (isReadOnly || !item || item.isDisabled) return;
    const next = selected ? [...new Set([...completed, key])] : completed.filter(id => id !== key);
    if (completedKeys === undefined) setInternalKeys(next);
    onCompletedChange?.(next);
  }
  function toggleExpanded() {
    if (isExpanded === undefined) setInternalExpanded(!expanded);
    onExpandedChange?.(!expanded);
  }
  function dismiss() {
    if (isOpen === undefined) setInternalOpen(false);
    onOpenChange?.(false);
    onDismiss?.();
  }
  return <AnimatePresence initial={false}>{open && <motion.div className={cx('ui-onboarding-checklist', className)} initial={reduced ? false : { opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }} transition={{ duration: reduced ? 0 : .24, ease: [.2,.75,.25,1] }}>
    <ChecklistSurface variant={variant} padding="none" data-density={density}>
      <CardHeader title={title} description={description} actions={<>{!!items.length && <IconButton icon={RiArrowDownSLine} variant="ghost" size="xs" aria-label={`${expanded ? 'Collapse' : 'Expand'} ${title}`} aria-expanded={expanded} aria-controls={id} onClick={toggleExpanded}/>}{dismissible && <CloseButton size="xs" aria-label={`Dismiss ${title}`} onClick={dismiss}/>}</>}/>
      {!!required.length && <Progress label={title} hideLabel value={done} maxValue={required.length} valueLabel={`${done} of ${required.length} complete`} tone={complete ? 'success' : 'accent'} className="ui-onboarding-checklist__progress"/>}
      {items.length ? <Collapsible id={id} isOpen={expanded}><ol className="ui-onboarding-checklist__list">{items.map((item, index) => <li key={item.id} data-complete={completed.includes(item.id) || undefined}>
        <Checkbox aria-label={item.title} aria-describedby={[item.isOptional && `${id}-${index}-optional`, item.description && `${id}-${index}-description`].filter(Boolean).join(' ') || undefined} isSelected={completed.includes(item.id)} isDisabled={item.isDisabled} isReadOnly={isReadOnly} onChange={selected => changeCompleted(item.id, selected)}><strong>{item.title}</strong>{item.isOptional && <span id={`${id}-${index}-optional`} className="ui-onboarding-checklist__optional">Optional</span>}{item.description && <span id={`${id}-${index}-description`} className="ui-onboarding-checklist__description">{item.description}</span>}</Checkbox>
        {item.action && <Button size="small" variant={item.action.variant ?? 'outline'} disabled={item.isDisabled} isLoading={item.action.isLoading} onClick={item.action.onPress}>{item.action.label}</Button>}
      </li>)}</ol></Collapsible> : <EmptyState size="small" title="No setup tasks" description="Your workspace has no pending setup tasks."/>}
      {footer && <div className="ui-onboarding-checklist__footer">{footer}</div>}
    </ChecklistSurface>
  </motion.div>}</AnimatePresence>;
}

'use client';

import { useCallback, useSyncExternalStore } from 'react';

export function useMediaQuery(query: string) {
  const subscribe = useCallback((notify: () => void) => {
    const media = window.matchMedia(query);
    media.addEventListener('change', notify);
    return () => media.removeEventListener('change', notify);
  }, [query]);
  const snapshot = useCallback(() => window.matchMedia(query).matches, [query]);
  return useSyncExternalStore(subscribe, snapshot, () => false);
}

// Keep these in sync with the navigation and inspector media queries in template CSS.
export const TEMPLATE_NAV_QUERY = '(max-width: 1023px)';
export const TEMPLATE_PANEL_QUERY = '(max-width: 1279px)';

'use client';

import {useLayoutEffect,useState,type RefObject} from 'react';

export type MotionTokens={fast:number;standard:number;settle:number;ease:[number,number,number,number]};
const defaults:MotionTokens={fast:.16,standard:.24,settle:.36,ease:[.2,.75,.25,1]};
function seconds(value:string,fallback:number){const match=value.trim().match(/^([\d.]+)(ms|s)$/);if(!match)return fallback;const amount=Number(match[1])/(match[2]==='ms'?1000:1);return Number.isFinite(amount)&&amount>=0?amount:fallback;}

/** Use the same scoped CSS tokens for JavaScript layout/glyph animation. */
export function useMotionTokens(scope?:RefObject<Element|null>){
  const [tokens,setTokens]=useState<MotionTokens>(defaults);
  useLayoutEffect(()=>{
    const element=scope?.current??document.documentElement;
    function read(){
      const style=getComputedStyle(element),curve=style.getPropertyValue('--motion-ease').match(/^\s*cubic-bezier\(([^)]+)\)/)?.[1].split(',').map(Number);
      const ease=curve?.length===4&&curve.every(Number.isFinite)?curve as MotionTokens['ease']:defaults.ease;
      const next={fast:seconds(style.getPropertyValue('--motion-fast'),defaults.fast),standard:seconds(style.getPropertyValue('--motion-standard'),defaults.standard),settle:seconds(style.getPropertyValue('--motion-settle'),defaults.settle),ease};
      setTokens(current=>current.fast===next.fast&&current.standard===next.standard&&current.settle===next.settle&&current.ease.every((value,index)=>value===next.ease[index])?current:next);
    }
    read();const observer=new MutationObserver(read);
    observer.observe(document.documentElement,{attributes:true,attributeFilter:['style','class','data-accent']});
    if(element!==document.documentElement)observer.observe(element,{attributes:true,attributeFilter:['style','class']});
    return()=>observer.disconnect();
  },[scope]);
  return tokens;
}

import { extendTailwindMerge } from 'tailwind-merge';

const typeFamilies = [
  'large-title', 'display-1', 'display-2', 'display-3', 'display-4',
  'title-1', 'title-2', 'title-3', 'headline', 'body', 'body-2',
  'caption-1', 'caption-2',
] as const;
const weights = ['regular', 'medium', 'semibold', 'bold'] as const;

// Custom text styles share Tailwind's text-* namespace with colors.
// Registering them keeps both classes when they appear together.
export const cx = extendTailwindMerge({
  extend: {
    classGroups: {
      'font-size': [{ text: typeFamilies.flatMap((family) => weights.map((weight) => `${family}-${weight}`)) }],
    },
  },
});
